                  : method === 'nodes.removeAlternative' ? { ...parsed, method: 'alternative-remove' }
                  : method === 'nodes.sidePanel' ? { ...parsed, method: 'side-panel' }
                  : method === 'nodes.selectRevision' ? { ...parsed, method: 'revision-select' }
